def perform_operation(num1, num2, operator):
    """Perform the given arithmetic operation on two numbers."""
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        try:
            return num1 / num2
        except ZeroDivisionError:
            print("Error: Division by zero is not allowed.")
            return None
    elif operator == '%':
        return num1 % num2
    else:
        print("Error: Invalid operator. Please use +, -, *, /, or %.")
        return None

